# SPDX-License-Identifier: MPL-2.0

defmodule Hypatia.Rules.ActionsLockTest do
  use ExUnit.Case, async: true

  alias Hypatia.Rules.ActionsLock
  alias Hypatia.Rules

  @valid_lock """
  # This file is machine-generated by `gh actions-lock`.
  version: 'v0.0.2'
  workflows:
      '.github/workflows/ci.yml':
          - 'actions/checkout@v7.0.1'
      '.github/workflows/other.yml': []
  dependencies:
      'actions/checkout@v7.0.1':
          ref: 'v7.0.1'
          commit: 'sha1-3d3c42e5aac5ba805825da76410c181273ba90b1'
          owner_id: 44036562
          repo_id: 197814629
  """

  @workflow """
  permissions:
    contents: read
  jobs:
    test:
      steps:
        - uses: actions/checkout@v7.0.1
  """

  test "valid lock pins only the associated workflow and exact ref" do
    assert {:ok, lock} = ActionsLock.parse(@valid_lock)
    assert ActionsLock.pinned?(lock, "ci.yml", "actions/checkout@v7.0.1")
    assert ActionsLock.pinned?(lock, ".github/workflows/ci.yml", "Actions/Checkout@v7.0.1")

    refute ActionsLock.pinned?(lock, "other.yml", "actions/checkout@v7.0.1")
    refute ActionsLock.pinned?(lock, "ci.yml", "actions/checkout@v6.0.0")
  end

  test "accepts uppercase hexadecimal commit suffixes" do
    lock =
      String.replace(
        @valid_lock,
        "3d3c42e5aac5ba805825da76410c181273ba90b1",
        "3D3C42E5AAC5BA805825DA76410C181273BA90B1"
      )

    assert {:ok, parsed} = ActionsLock.parse(lock)
    assert ActionsLock.pinned?(parsed, "ci.yml", "actions/checkout@v7.0.1")
  end

  test "normalises repository identity but preserves case-sensitive refs" do
    lock = String.replace(@valid_lock, "v7.0.1", "ReleaseV7")

    assert {:ok, parsed} = ActionsLock.parse(lock)
    assert ActionsLock.pinned?(parsed, "ci.yml", "Actions/Checkout@ReleaseV7")
    refute ActionsLock.pinned?(parsed, "ci.yml", "actions/checkout@releasev7")
  end

  test "rejects missing, short, and non-hex commit fields" do
    missing = Regex.replace(~r/^\s*commit:.*\n/m, @valid_lock, "")

    short =
      String.replace(
        @valid_lock,
        "sha1-3d3c42e5aac5ba805825da76410c181273ba90b1",
        "sha1-1234"
      )

    non_hex =
      String.replace(
        @valid_lock,
        "sha1-3d3c42e5aac5ba805825da76410c181273ba90b1",
        "sha1-zd3c42e5aac5ba805825da76410c181273ba90b1"
      )

    assert {:error, {:line, _, {:missing_dependency_field, _, :commit}}} =
             ActionsLock.parse(missing)

    assert {:error, {:line, _, :malformed_dependency_commit}} = ActionsLock.parse(short)
    assert {:error, {:line, _, :malformed_dependency_commit}} = ActionsLock.parse(non_hex)
  end

  test "accepts lockfile v0.0.3, which gh-actions-lock v0.2.0 writes, with the same grammar" do
    v003 = String.replace(@valid_lock, "version: 'v0.0.2'", "version: 'v0.0.3'")

    assert {:ok, lock} = ActionsLock.parse(v003)
    assert lock.version == "v0.0.3"
    assert ActionsLock.pinned?(lock, "ci.yml", "actions/checkout@v7.0.1")
    refute ActionsLock.pinned?(lock, "other.yml", "actions/checkout@v7.0.1")

    # The grammar is shared, not loosened: a malformed v0.0.3 lock still fails closed.
    malformed = String.replace(v003, ~r/sha1-[0-9a-f]{40}/, "sha1-short")
    assert {:error, {:line, _, :malformed_dependency_commit}} = ActionsLock.parse(malformed)
  end

  test "v0.0.3 hostname: github.com is the default, a GHE.com tenant host is refused" do
    v003 = String.replace(@valid_lock, "version: 'v0.0.2'", "version: 'v0.0.3'")

    with_host = fn lock, host ->
      String.replace(
        lock,
        "        repo_id: 197814629",
        "        repo_id: 197814629\n        hostname: '#{host}'"
      )
    end

    assert {:ok, lock} = ActionsLock.parse(with_host.(v003, "github.com"))
    assert ActionsLock.pinned?(lock, "ci.yml", "actions/checkout@v7.0.1")

    assert {:error, {:line, 13, {:unsupported_dependency_hostname, "acme.ghe.com"}}} =
             ActionsLock.parse(with_host.(v003, "acme.ghe.com"))

    # The field is new in v0.0.3; a v0.0.2 lock carrying it is refused.
    assert {:error, {:line, 13, {:hostname_not_in_version, "v0.0.2"}}} =
             ActionsLock.parse(with_host.(@valid_lock, "github.com"))

    duplicate = with_host.(with_host.(v003, "github.com"), "github.com")

    assert {:error, {:line, _, {:duplicate_dependency_field, _, :hostname}}} =
             ActionsLock.parse(duplicate)
  end

  test "rejects every version outside the supported set, and a second version line" do
    for version <- ["v0.0.1", "v0.0.4", "v0.1.0", "0.0.3"] do
      assert {:error, {:line, 2, {:unsupported_version, ^version}}} =
               @valid_lock
               |> String.replace("version: 'v0.0.2'", "version: '#{version}'")
               |> ActionsLock.parse()
    end

    twice =
      String.replace(@valid_lock, "version: 'v0.0.2'", "version: 'v0.0.2'\nversion: 'v0.0.3'")

    assert {:error, {:line, 3, :duplicate_version}} = ActionsLock.parse(twice)
  end

  test "rejects unsupported versions and missing dependency entries" do
    assert {:error, {:line, 2, {:unsupported_version, "v9"}}} =
             @valid_lock
             |> String.replace("v0.0.2", "v9")
             |> ActionsLock.parse()

    missing_dependency = """
    version: 'v0.0.2'
    workflows:
        '.github/workflows/ci.yml':
            - 'actions/checkout@v7.0.1'
    dependencies:
    """

    assert {:error, {:workflow_dependencies_missing, [{_, "actions/checkout@v7.0.1"}]}} =
             ActionsLock.parse(missing_dependency)
  end

  # #926: `gh actions-lock` began writing v0.0.3: the v0.0.2 line grammar plus
  # an optional dependency `hostname` (github/actions-lockfile lockfile-v0.0.3.json).
  describe "format v0.0.3" do
    @v3_lock String.replace(@valid_lock, "version: 'v0.0.2'", "version: 'v0.0.3'")

    test "is accepted, and records the version it was read as" do
      assert {:ok, lock} = ActionsLock.parse(@v3_lock)
      assert lock.version == "v0.0.3"
      assert ActionsLock.pinned?(lock, "ci.yml", "actions/checkout@v7.0.1")
      refute ActionsLock.pinned?(lock, "other.yml", "actions/checkout@v7.0.1")

      assert {:ok, %{version: "v0.0.2"}} = ActionsLock.parse(@valid_lock)
    end

    test "is held to the same grammar: a malformed line still fails closed" do
      short = String.replace(@v3_lock, ~r/sha1-[0-9a-f]{40}/, "sha1-1234")
      assert {:error, {:line, _, :malformed_dependency_commit}} = ActionsLock.parse(short)

      unknown =
        String.replace(@v3_lock, "        repo_id:", "        integrity: 'x'\n        repo_id:")

      assert {:error, {:line, _, :malformed_dependency_entry}} = ActionsLock.parse(unknown)
    end

    test "accepts and records the optional dependency hostname (home host only)" do
      lock =
        String.replace(
          @v3_lock,
          "        owner_id:",
          "        hostname: 'github.com'\n        owner_id:"
        )

      assert {:ok, parsed} = ActionsLock.parse(lock)
      assert parsed.dependencies["actions/checkout@v7.0.1"].hostname == "github.com"
      assert ActionsLock.pinned?(parsed, "ci.yml", "actions/checkout@v7.0.1")

      # A well-formed tenant host is refused by POLICY (see the moduledoc:
      # owner_id/repo_id are host-scoped and the association keys carry no
      # host). Asserting that it parses would mean the oracle accepts a pin it
      # cannot associate with a workflow.
      tenant = String.replace(lock, "github.com", "octocorp.ghe.com")

      assert {:error, {:line, _, {:unsupported_dependency_hostname, "octocorp.ghe.com"}}} =
               ActionsLock.parse(tenant)

      assert {:ok, parsed} = ActionsLock.parse(@v3_lock)
      assert parsed.dependencies["actions/checkout@v7.0.1"].hostname == nil
    end

    test "scopes owner/repo identity checks to the dependency's host" do
      # Same owner name and repo, different numeric IDs: a conflict within one
      # host, but legitimate across hosts (IDs are numbered per instance).
      two_pins = """
      version: 'v0.0.3'
      workflows:
          '.github/workflows/ci.yml':
              - 'actions/checkout@v7.0.1'
              - 'actions/setup-node@v7.0.0'
      dependencies:
          'actions/checkout@v7.0.1':
              ref: 'v7.0.1'
              commit: 'sha1-3d3c42e5aac5ba805825da76410c181273ba90b1'
              owner_id: 44036562
              repo_id: 197814629
          'actions/setup-node@v7.0.0':
              HOST
              ref: 'v7.0.0'
              commit: 'sha1-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa'
              owner_id: 99
              repo_id: 12345
      """

      same_host = Regex.replace(~r/^ *HOST\n/m, two_pins, "")

      assert {:error, {:line, _, {:owner_identity_mismatch, "actions", 44_036_562, 99}}} =
               ActionsLock.parse(same_host)

      # The cross-host case is unreachable: a tenant hostname is refused before
      # identity scoping is consulted, precisely because two hosts cannot be
      # told apart in the `owner/repo@ref` association keys.
      cross_host = String.replace(two_pins, "HOST", "hostname: 'octocorp.ghe.com'")

      assert {:error, {:line, _, {:unsupported_dependency_hostname, "octocorp.ghe.com"}}} =
               ActionsLock.parse(cross_host)
    end

    test "refuses a malformed, repeated, or v0.0.2 hostname" do
      with_host = fn host ->
        String.replace(
          @v3_lock,
          "        owner_id:",
          "        hostname: '#{host}'\n        owner_id:"
        )
      end

      for bad <- [
            "Octocorp.ghe.com",
            "https://github.com",
            "github.com:443",
            "evil.example.com",
            "",
            "a.ghe.com/x"
          ] do
        assert {:error, {:line, _, reason}} = ActionsLock.parse(with_host.(bad))
        assert reason in [:malformed_dependency_hostname, {:malformed_dependency_hostname, bad}]
      end

      twice =
        String.replace(
          with_host.("github.com"),
          "        owner_id:",
          "        hostname: 'github.com'\n        owner_id:"
        )

      assert {:error, {:line, _, {:duplicate_dependency_field, _, :hostname}}} =
               ActionsLock.parse(twice)

      v2 = String.replace(with_host.("github.com"), "v0.0.3", "v0.0.2")

      assert {:error, {:line, _, {:hostname_not_in_version, "v0.0.2"}}} =
               ActionsLock.parse(v2)
    end

    test "negative control: a version past v0.0.3 is still refused" do
      assert {:error, {:line, 2, {:unsupported_version, "v0.0.4"}}} =
               @valid_lock
               |> String.replace("v0.0.2", "v0.0.4")
               |> ActionsLock.parse()
    end

    test "a second version line is refused, even when both are supported" do
      twice =
        String.replace(@v3_lock, "version: 'v0.0.3'\n", "version: 'v0.0.3'\nversion: 'v0.0.2'\n")

      assert {:error, {:line, 3, :duplicate_version}} = ActionsLock.parse(twice)
    end
  end

  test "rejects symbolic-ref and SHA-key contradictions" do
    symbolic = String.replace(@valid_lock, "ref: 'v7.0.1'", "ref: 'v6.0.0'")

    assert {:error, {:line, _, {:symbolic_key_ref_mismatch, _, _}}} = ActionsLock.parse(symbolic)

    sha_key = """
    version: 'v0.0.2'
    workflows:
        '.github/workflows/ci.yml':
            - 'actions/checkout@aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa'
    dependencies:
        'actions/checkout@aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa':
            ref: 'v7.0.1'
            commit: 'sha1-bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb'
            owner_id: 44036562
            repo_id: 197814629
    """

    assert {:error, {:line, _, {:sha_key_commit_mismatch, _}}} = ActionsLock.parse(sha_key)
  end

  test "requires each positive repository identity exactly once" do
    for field <- [:owner_id, :repo_id] do
      missing = Regex.replace(~r/^\s*#{field}:.*\n/m, @valid_lock, "")

      assert {:error, {:line, _, {:missing_dependency_field, _, ^field}}} =
               ActionsLock.parse(missing)
    end

    zero = String.replace(@valid_lock, "owner_id: 44036562", "owner_id: 0")

    assert {:error, {:line, _, {:nonpositive_dependency_identity, "owner_id"}}} =
             ActionsLock.parse(zero)

    malformed = String.replace(@valid_lock, "repo_id: 197814629", "repo_id: unknown")
    assert {:error, {:line, _, :malformed_dependency_identity}} = ActionsLock.parse(malformed)

    duplicate =
      String.replace(
        @valid_lock,
        "owner_id: 44036562",
        "owner_id: 44036562\n        owner_id: 44036562"
      )

    assert {:error, {:line, _, {:duplicate_dependency_field, _, :owner_id}}} =
             ActionsLock.parse(duplicate)
  end

  test "rejects contradictory owner and repository identities" do
    contradictory_owner = """
    version: 'v0.0.2'
    workflows:
        '.github/workflows/ci.yml': []
    dependencies:
        'actions/checkout@v7':
            ref: 'v7'
            commit: 'sha1-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa'
            owner_id: 44036562
            repo_id: 197814629
        'actions/cache@v6':
            ref: 'v6'
            commit: 'sha1-bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb'
            owner_id: 999
            repo_id: 215566462
    """

    assert {:error, {:line, _, {:owner_identity_mismatch, "actions", 44_036_562, 999}}} =
             ActionsLock.parse(contradictory_owner)

    contradictory_repo =
      contradictory_owner
      |> String.replace("'actions/cache@v6'", "'actions/checkout@v6'")
      |> String.replace("owner_id: 999", "owner_id: 44036562")

    assert {:error,
            {:line, _,
             {:repository_identity_mismatch, "actions/checkout", 197_814_629, 215_566_462}}} =
             ActionsLock.parse(contradictory_repo)
  end

  test "rejects a repository id reused by a different repository" do
    reused_id = """
    version: 'v0.0.2'
    workflows:
        '.github/workflows/ci.yml': []
    dependencies:
        'actions/checkout@v7':
            ref: 'v7'
            commit: 'sha1-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa'
            owner_id: 44036562
            repo_id: 197814629
        'other/cache@v6':
            ref: 'v6'
            commit: 'sha1-bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb'
            owner_id: 123
            repo_id: 197814629
    """

    assert {:error,
            {:line, _, {:repository_id_reused, 197_814_629, "actions/checkout", "other/cache"}}} =
             ActionsLock.parse(reused_id)
  end

  test "validates and resolves transitive dependency entries" do
    transitive = """
    version: 'v0.0.2'
    workflows:
        '.github/workflows/ci.yml':
            - 'owner/composite@v1'
    dependencies:
        'owner/composite@v1':
            ref: 'v1'
            commit: 'sha1-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa'
            owner_id: 1
            repo_id: 2
            uses:
                - 'other/child@bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb'
        'other/child@bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb':
            ref: 'v2'
            commit: 'sha1-bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb'
            owner_id: 3
            repo_id: 4
    """

    assert {:ok, parsed} = ActionsLock.parse(transitive)

    assert parsed.dependencies["owner/composite@v1"].uses ==
             MapSet.new(["other/child@bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"])

    missing =
      Regex.replace(
        ~r/^    'other\/child@bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb':.*\z/ms,
        transitive,
        ""
      )

    assert {:error, {:transitive_dependencies_missing, [{"owner/composite@v1", _}]}} =
             ActionsLock.parse(missing)

    duplicate =
      String.replace(
        transitive,
        "            - 'other/child@bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb'",
        "            - 'other/child@bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb'\n" <>
          "            - 'other/child@bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb'"
      )

    assert {:error, {:line, _, {:duplicate_transitive_ref, "owner/composite@v1", _}}} =
             ActionsLock.parse(duplicate)
  end

  test "rejects non-canonical dependency keys" do
    subpath_key =
      String.replace(
        @valid_lock,
        "    'actions/checkout@v7.0.1':\n",
        "    'actions/checkout/subpath@v7.0.1':\n"
      )

    colon_key =
      String.replace(
        @valid_lock,
        "    'actions/checkout@v7.0.1':\n",
        "    'actions/checkout@refs:heads/main':\n"
      )

    assert {:error, {:line, _, {:malformed_dependency_key, _}}} = ActionsLock.parse(subpath_key)

    assert {:error, {:line, _, {:malformed_dependency_key, _}}} = ActionsLock.parse(colon_key)
  end

  test "accepts v0.0.3 locks and validates the optional hostname" do
    v3 = String.replace(@valid_lock, "v0.0.2", "v0.0.3")
    assert {:ok, %ActionsLock{version: "v0.0.3"}} = ActionsLock.parse(v3)

    with_host = fn host ->
      String.replace(
        v3,
        "        repo_id: 197814629\n",
        "        repo_id: 197814629\n        hostname: '#{host}'\n"
      )
    end

    assert {:ok, _} = ActionsLock.parse(with_host.("github.com"))

    # Well-formed *.ghe.com tenant hosts are refused by POLICY, not by the
    # grammar: owner_id/repo_id are host-scoped and the `owner/repo@ref`
    # association keys carry no host, so accepting a tenant host would let a
    # tenant pin be associated with a github.com workflow. This module's
    # moduledoc has said "fail closed" since the reorg; the assertions here
    # used to accept them, written against an implementation that never
    # shipped and never compiled.
    assert {:error, {:line, _, {:unsupported_dependency_hostname, "acme.ghe.com"}}} =
             ActionsLock.parse(with_host.("acme.ghe.com"))

    long_label = String.duplicate("a", 64) <> ".ghe.com"

    # 63 characters is a legal DNS label, so it fails as a policy choice; 64 is
    # not, so it fails as malformed.
    assert {:error, {:line, _, {:unsupported_dependency_hostname, _}}} =
             ActionsLock.parse(with_host.(String.duplicate("a", 63) <> ".ghe.com"))

    for bad <- [
          "GitHub.com",
          "example.com",
          "acme.ghe.com.evil",
          "-x.ghe.com",
          "foo.bar.ghe.com",
          long_label
        ] do
      assert {:error, {:line, _, {:malformed_dependency_hostname, ^bad}}} =
               ActionsLock.parse(with_host.(bad))
    end

    dup =
      String.replace(
        with_host.("github.com"),
        "hostname: 'github.com'\n",
        "hostname: 'github.com'\n        hostname: 'github.com'\n"
      )

    assert {:error, {:line, _, {:duplicate_dependency_field, _, :hostname}}} =
             ActionsLock.parse(dup)

    v2_with_host =
      String.replace(
        @valid_lock,
        "        repo_id: 197814629\n",
        "        repo_id: 197814629\n        hostname: 'github.com'\n"
      )

    assert {:error, {:line, _, {:hostname_not_in_version, "v0.0.2"}}} =
             ActionsLock.parse(v2_with_host)
  end

  test "scopes owner and repository identities to their v0.0.3 host" do
    mixed = """
    version: 'v0.0.3'
    workflows:
        '.github/workflows/ci.yml':
            - 'acme/foo@v1'
            - 'acme/bar@v1'
    dependencies:
        'acme/bar@v1':
            hostname: 'github.com'
            ref: 'v1'
            commit: 'sha1-3d3c42e5aac5ba805825da76410c181273ba90b1'
            owner_id: 2
            repo_id: 20
        'acme/foo@v1':
            ref: 'v1'
            commit: 'sha1-3d3c42e5aac5ba805825da76410c181273ba90b1'
            owner_id: 1
            repo_id: 20
    """

    assert {:ok, lock} = ActionsLock.parse(mixed)
    assert lock.dependencies["acme/bar@v1"].hostname == "github.com"
    assert lock.dependencies["acme/foo@v1"].hostname == nil

    same_host = String.replace(mixed, "        hostname: 'github.com'\n", "")

    assert {:error, {:line, _, {:owner_identity_mismatch, "acme", 2, 1}}} =
             ActionsLock.parse(same_host)
  end

  test "an omitted hostname and an explicit github.com are one identity scope" do
    # Same conflict as above, but spelled two ways: `acme/bar` names the home
    # host explicitly, `acme/foo` omits it. Both bind to github.com, so the
    # owner-id disagreement must still be caught. Comparing raw values made
    # these two scopes and silently skipped the check (Codex review, P1).
    split = """
    version: 'v0.0.3'
    workflows:
        '.github/workflows/ci.yml':
            - 'acme/bar@v1'
            - 'acme/foo@v1'
    dependencies:
        'acme/bar@v1':
            hostname: 'github.com'
            ref: 'v1'
            commit: 'sha1-3d3c42e5aac5ba805825da76410c181273ba90b1'
            owner_id: 2
            repo_id: 20
        'acme/foo@v1':
            ref: 'v1'
            commit: 'sha1-3d3c42e5aac5ba805825da76410c181273ba90b1'
            owner_id: 1
            repo_id: 20
    """

    assert {:error, {:line, _, {:owner_identity_mismatch, "acme", 2, 1}}} =
             ActionsLock.parse(split)

    # ... and agreeing identities across the two spellings stay legal. (repo_id
    # must differ too: the same repo_id on two different repositories is its
    # own defect, `:repository_id_reused`.)
    agreeing =
      String.replace(
        split,
        "            owner_id: 1\n            repo_id: 20",
        "            owner_id: 2\n            repo_id: 21"
      )

    assert {:ok, _} = ActionsLock.parse(agreeing)
  end

  test "parses the repository's authoritative generated lockfile" do
    content = File.read!(".github/workflows/actions.lock")
    assert {:ok, parsed} = ActionsLock.parse(content)
    assert map_size(parsed.workflows) > 0
    assert map_size(parsed.dependencies) > 0
  end

  test "v0.0.3 retains workflow association and fails closed on malformed dependencies" do
    content = String.replace(@valid_lock, "v0.0.2", "v0.0.3")

    assert {:ok, parsed} = ActionsLock.parse(content)
    assert parsed.version == "v0.0.3"
    assert ActionsLock.pinned?(parsed, "ci.yml", "actions/checkout@v7.0.1")
    refute ActionsLock.pinned?(parsed, "other.yml", "actions/checkout@v7.0.1")

    malformed = String.replace(content, ~r/sha1-[0-9a-f]{40}/, "sha1-short")
    assert {:error, {:line, _, :malformed_dependency_commit}} = ActionsLock.parse(malformed)

    duplicate = String.replace(content, "workflows:", "version: 'v0.0.3'\nworkflows:")
    assert {:error, {:line, _, :duplicate_version}} = ActionsLock.parse(duplicate)
  end

  describe "v0.0.3 hostname field" do
    @standards_v003 "test/fixtures/actions_lock/standards-b3ce78e-v0.0.3.lock"

    @v003_lock """
    # This file is machine-generated by `gh actions-lock`.
    version: 'v0.0.3'
    workflows:
        '.github/workflows/ci.yml':
            - 'actions/checkout@v7.0.1'
    dependencies:
        'actions/checkout@v7.0.1':
            hostname: 'github.com'
            ref: 'v7.0.1'
            commit: 'sha1-3d3c42e5aac5ba805825da76410c181273ba90b1'
            owner_id: 44036562
            repo_id: 197814629
    """

    defp with_hostname(value) do
      String.replace(@v003_lock, "hostname: 'github.com'", "hostname: #{value}")
    end

    test "parses hyperpolymath/standards' generated v0.0.3 lockfile" do
      assert {:ok, parsed} = ActionsLock.parse(File.read!(@standards_v003))

      assert parsed.version == "v0.0.3"
      assert map_size(parsed.workflows) == 57
      assert map_size(parsed.dependencies) == 28
      # This fixture predates gh-actions-lock emitting `hostname:`, so every
      # dependency records nil — which IS the home host (`github.com`); the
      # field is deliberately not defaulted to the string. See
      # finalize_dependency/1 and scope_to_host/2.
      assert Enum.all?(Map.values(parsed.dependencies), &is_nil(&1.hostname))

      checkout = "actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1"
      assert ActionsLock.pinned?(parsed, "actions-lock-gate.yml", checkout)
      assert parsed.workflows[".github/workflows/changelog.yml"] == MapSet.new()

      assert MapSet.member?(
               parsed.dependencies[
                 "hyperpolymath/standards@427eb35c40552d912d8c757518e8326f0d20f597"
               ].uses,
               checkout
             )
    end

    test "an omitted hostname binds the pin to github.com (recorded as nil)" do
      omitted = String.replace(@v003_lock, "        hostname: 'github.com'\n", "")

      assert {:ok, parsed} = ActionsLock.parse(omitted)
      # nil IS the home host in the record. Defaulting the stored field to the
      # string would break scope_to_host/2, which compares it against the raw
      # value each record carries; see finalize_dependency/1.
      assert parsed.dependencies["actions/checkout@v7.0.1"].hostname == nil
      assert ActionsLock.pinned?(parsed, "ci.yml", "actions/checkout@v7.0.1")
    end

    test "an explicit github.com hostname is accepted and keeps association" do
      assert {:ok, parsed} = ActionsLock.parse(@v003_lock)
      assert parsed.dependencies["actions/checkout@v7.0.1"].hostname == "github.com"
      assert ActionsLock.pinned?(parsed, "ci.yml", "actions/checkout@v7.0.1")
      refute ActionsLock.pinned?(parsed, "other.yml", "actions/checkout@v7.0.1")
    end

    test "v0.0.2 lockfiles default to github.com and may not carry a hostname" do
      assert {:ok, parsed} = ActionsLock.parse(@valid_lock)
      assert parsed.dependencies["actions/checkout@v7.0.1"].hostname == nil

      v002 = String.replace(@v003_lock, "v0.0.3", "v0.0.2")

      assert {:error, {:line, 8, {:hostname_not_in_version, "v0.0.2"}}} =
               ActionsLock.parse(v002)
    end

    test "a well-formed GHE.com tenant hostname fails closed" do
      assert {:error, {:line, 8, {:unsupported_dependency_hostname, "octocorp.ghe.com"}}} =
               ActionsLock.parse(with_hostname("'octocorp.ghe.com'"))
    end

    test "non-canonical hostnames are malformed" do
      for value <- [
            "",
            "GitHub.com",
            "https://github.com",
            "github.com:443",
            "github.com/",
            " github.com",
            "github.com.evil.example",
            "-tenant.ghe.com",
            "a.b.ghe.com"
          ] do
        assert {:error, {:line, 8, {:malformed_dependency_hostname, ^value}}} =
                 ActionsLock.parse(with_hostname("'#{value}'")),
               "expected #{inspect(value)} to be rejected"
      end
    end

    test "unquoted, double-quoted, and duplicate hostnames fail closed" do
      for value <- ["github.com", ~s("github.com")] do
        assert {:error, {:line, 8, :malformed_dependency_hostname}} =
                 ActionsLock.parse(with_hostname(value))
      end

      duplicate =
        String.replace(
          @v003_lock,
          "hostname: 'github.com'",
          "hostname: 'github.com'\n        hostname: 'github.com'"
        )

      assert {:error, {:line, 9, {:duplicate_dependency_field, _, :hostname}}} =
               ActionsLock.parse(duplicate)
    end

    test "a hostname outside a dependency entry fails closed" do
      orphan =
        String.replace(
          @v003_lock,
          "    'actions/checkout@v7.0.1':\n        hostname",
          "        hostname"
        )

      assert {:error, {:line, 7, :dependency_field_without_dependency}} =
               ActionsLock.parse(orphan)
    end

    test "versions after v0.0.3 still fail closed" do
      for version <- ["v0.0.4", "v0.1.0", "v1.0.0"] do
        assert {:error, {:line, 2, {:unsupported_version, ^version}}} =
                 @v003_lock |> String.replace("v0.0.3", version) |> ActionsLock.parse()
      end
    end
  end

  test "legacy Rules workflow scanner delegates to path-aware lock semantics" do
    assert Rules.scan_workflow(@workflow, filename: "ci.yml", actions_lock: @valid_lock) == []

    findings = Rules.scan_workflow(@workflow, filename: "other.yml", actions_lock: @valid_lock)
    assert Enum.any?(findings, &(&1.rule == "unpinned_action"))

    malformed = String.replace(@valid_lock, ~r/sha1-[0-9a-f]{40}/, "sha1-short")
    findings = Rules.scan_workflow(@workflow, filename: "ci.yml", actions_lock: malformed)
    assert Enum.any?(findings, &(&1.rule == "invalid_actions_lock"))
    refute Enum.any?(findings, &(&1.rule == "unpinned_action"))
  end
end
